export type FlowGlyphName = keyof typeof GLYPHS

/** One of the reference app's menu glyphs; `size` defaults to the 16px menu icon slot (14px glyphs keep their box). */
export function FlowGlyph({ name, size, ...props }: SVGProps<SVGSVGElement> & { name: FlowGlyphName; size?: number }) {
  const [viewBox, paths] = GLYPHS[name]
  const box = size ?? Number(viewBox.split(' ')[3])
  return <svg aria-hidden="true" focusable="false" width={box} height={box} viewBox={viewBox} fill="currentColor" data-flow-glyph={name} {...props}>
    {paths.map((path, index) => path.startsWith('e:')
      ? <path key={index} d={path.slice(2)} fillRule="evenodd" clipRule="evenodd"/>
      : <path key={index} d={path}/>)}
  </svg>
}
